<script setup lang="ts">
import {ElButton, ElDialog, ElInput, ElSelect, ElOption, ElTable, ElTableColumn, ElPagination, vLoading} from 'element-plus'
import {computed,ref,watch} from 'vue'
import {api,type Account} from '../../api'
import {base,reasonText,money,incomeLabel,type DiningOrder,type Restaurant,type PageResult} from './types'
import './dining.css'
import AdminListPager from '../../shared/list/AdminListPager.vue'
import AdminStatusBadge from '../../shared/list/AdminStatusBadge.vue'
import AdminSelectedRowsDialog from '../../shared/list/AdminSelectedRowsDialog.vue'
import AdminSelectionBar from '../../shared/list/AdminSelectionBar.vue'
import OrderActionDialog from '../orders/OrderActionDialog.vue'
import {orderActions,actionLabels,pendingActions,actionPermission,type OrderAction} from '../orders/order-actions.mjs'
import type {Order} from '../orders/types'
const selectionVersion=ref(0)
const pageSize=ref(20)
const props=defineProps<{account:Account}>()
const operation=ref<OrderAction|null>(null),operationId=ref(''),operationOrders=ref<Record<string,Order>>({}),operationNotice=ref('')
function recoveries(id:string){return pendingActions(props.account.accountId,id,sessionStorage).filter(a=>props.account.permissionCodes.includes(actionPermission(a)))}
function openOperation(id:string,a:OrderAction){operationId.value=id;operation.value=a}
async function readOperations(){operationOrders.value={};if(!items.value.length||!props.account.permissionCodes.includes('order.read'))return;const current=generation;try{const result=await api<{items:Order[]}>(`/orders?${new URLSearchParams({orderIds:items.value.map(row=>row.id).join(','),page:'1',pageSize:String(pageSize.value)})}`);if(current===generation)operationOrders.value=Object.fromEntries(result.items.map(row=>[row.orderId,row]))}catch(e){if(current===generation)operationNotice.value=`订单操作状态读取失败：${reasonText(e)}`}}
function operationUpdated(row:Order){operationOrders.value={...operationOrders.value,[row.orderId]:row};void load()}
const items=ref<DiningOrder[]>([]),restaurants=ref<Restaurant[]>([]),restaurantId=ref(''),storeId=ref(''),search=ref(''),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),detail=ref<DiningOrder|null>(null),detailLoading=ref(false),detailError=ref(''),detailId=ref('')
const selected=ref<DiningOrder[]>([]),comparison=ref(false),status=ref('')
const comparisonRows=computed(()=>selected.value.map(r=>({orderNo:r.orderNo,restaurant:r.restaurantName,table:r.tableNumber,status:r.status,paid:money(r.payableFen),commission:money(r.commission.commissionFen)})))
const warehouses=ref<{id:string;name:string}[]>([])
let generation=0,detailGeneration=0
async function load(){const current=++generation;loading.value=true;items.value=[];selected.value=[];comparison.value=false;error.value='';try{const result=await api<PageResult<DiningOrder>>(`${base}/orders?${new URLSearchParams({restaurantId:restaurantId.value,storeId:storeId.value,search:search.value,status:status.value,page:String(page.value),pageSize:String(pageSize.value)})}`);if(current===generation){items.value=result.items;total.value=result.total;void readOperations()}}catch(e){if(current===generation)error.value=reasonText(e)}finally{if(current===generation)loading.value=false}}
async function view(id:string){const current=++detailGeneration;detailId.value=id;detail.value=null;detailError.value='';detailLoading.value=true;try{const result=await api<DiningOrder>(`${base}/orders/${id}`);if(current===detailGeneration)detail.value=result}catch(e){if(current===detailGeneration)detailError.value=reasonText(e)}finally{if(current===detailGeneration)detailLoading.value=false}}
function close(){detailGeneration++;detailId.value='';detail.value=null}
async function initialize(){restaurants.value=[];operation.value=null;operationOrders.value={};close();load();try{let restaurantPage=1,restaurantTotal=0;do{const result=await api<PageResult<Restaurant>>(`${base}/restaurants?pageSize=100&page=${restaurantPage++}`);restaurants.value=[...restaurants.value,...result.items];restaurantTotal=result.total;if(!result.items.length)break}while(restaurants.value.length<restaurantTotal);warehouses.value=[];let current=1,total=0;do{const result=await api<PageResult<{id:string;name:string}>>(`${base}/order-stores?pageSize=100&page=${current++}`);warehouses.value=[...warehouses.value,...result.items];total=result.total;if(!result.items.length)break}while(warehouses.value.length<total)}catch(e){error.value=`餐饮店筛选读取失败：${reasonText(e)}`}}
watch(()=>props.account.accountId,initialize,{immediate:true})
</script>
<template><section class="page-content dining-page admin-list-page"><header class="page-heading"><div><h1>餐饮联盟订单</h1><p>订单地址与桌号来自扫码时的餐饮店信息，由锁定前置仓履约。</p></div></header><p v-if="operationNotice" role="status">{{operationNotice}}</p><section class="panel admin-list-page"><form class="toolbar" @submit.prevent="page=1;load()"><el-select v-model="restaurantId" aria-label="筛选餐饮店" clearable placeholder="全部餐饮店" style="width:280px"><el-option v-for="r in restaurants" :key="r.id" :value="r.id" :label="r.name"/></el-select><el-select v-model="storeId" aria-label="履约前置仓" clearable placeholder="全部履约前置仓"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select><el-input v-model="search" aria-label="订单号" placeholder="搜索订单号" :maxlength="40" style="width:220px"/><el-select v-model="status" aria-label="订单状态" clearable placeholder="全部状态"><el-option label="待付款" value="PENDING_PAYMENT"/><el-option label="已付款" value="PAID"/><el-option label="已关闭" value="CLOSED"/></el-select><el-button native-type="submit" type="primary" :loading="loading">查询</el-button><el-button @click="search='';status='';restaurantId='';storeId='';page=1;load()">重置</el-button></form><p v-if="error" role="alert" class="error">{{error}} <el-button @click="initialize">重试</el-button></p><AdminSelectionBar :count="selected.length" :loading="loading" @clear="selected=[];selectionVersion++"><el-button :disabled="!selected.length" @click="comparison=true">对比所选订单</el-button></AdminSelectionBar><el-table :key="selectionVersion" class="admin-list-table" v-loading="loading" :data="items" empty-text="暂无餐饮联盟订单" @selection-change="selected=$event"><el-table-column type="selection" width="50"/><el-table-column prop="orderNo" label="订单号" min-width="180"/><el-table-column label="餐饮店 / 桌号" min-width="180"><template #default="{row}">{{row.restaurantName}} · {{row.tableNumber}}</template></el-table-column><el-table-column label="履约仓" min-width="160"><template #default="{row}">{{row.fulfillmentStore.name}}<p v-if="row.fulfillmentWarehouse">仓库：{{row.fulfillmentWarehouse.name}}</p></template></el-table-column><el-table-column label="状态" min-width="120"><template #default="{row}"><AdminStatusBadge :status="row.status" :label="({PENDING_PAYMENT:'待付款',PAID:'已付款',CLOSED:'已关闭'} as Record<string,string>)[row.status]||row.status"/></template></el-table-column><el-table-column label="实付" width="120"><template #default="{row}">{{money(row.payableFen)}}</template></el-table-column><el-table-column label="佣金" min-width="160"><template #default="{row}">{{money(row.commission.commissionFen)}} · {{incomeLabel(row.commission.status)}}</template></el-table-column><el-table-column label="操作" fixed="right" min-width="240"><template #default="{row}"><el-button link @click="view(row.id)">查看详情</el-button><template v-if="operationOrders[row.id]"><el-button v-for="a in orderActions(operationOrders[row.id]!,account.permissionCodes)" :key="a" link @click="openOperation(row.id,a)">{{actionLabels[a]}}</el-button></template><el-button v-for="a in recoveries(row.id)" :key="`recover-${a}`" link @click="openOperation(row.id,a)">核查{{actionLabels[a]}}结果</el-button></template></el-table-column></el-table><AdminListPager :page="page" :page-size="pageSize" :total="total" :loading="loading" @change="(p,s)=>{page=p;pageSize=s;load()}"/></section><el-dialog :model-value="!!detailId" title="联盟订单详情" width="min(980px,94vw)" :close-on-click-modal="false" @update:model-value="close"><section class="panel" aria-label="联盟订单详情"><header class="toolbar"><h2>订单详情</h2><el-button @click="close">关闭详情</el-button></header><p v-if="detailLoading" role="status">正在读取订单详情…</p><p v-if="detailError" role="alert" class="error">{{detailError}} <el-button @click="view(detailId)">重试</el-button></p><template v-if="detail"><p>{{detail.orderNo}} · {{detail.restaurantName}} · 桌号 {{detail.tableNumber}}</p><p>配送地址：{{detail.address}}</p><p>履约前置仓：{{detail.fulfillmentStore.name}}</p><p v-if="detail.fulfillmentWarehouse">履约仓库：{{detail.fulfillmentWarehouse.name}} · {{detail.fulfillmentWarehouse.id}}</p><el-table class="admin-list-table" :data="detail.lines"><el-table-column prop="productName" label="商品"/><el-table-column prop="skuCode" label="SKU"/><el-table-column label="数量"><template #default="{row}">{{row.quantity}} {{row.saleUnit}}</template></el-table-column><el-table-column label="实付"><template #default="{row}">{{money(row.payableFen)}}</template></el-table-column></el-table><p>佣金 {{money(detail.commission.commissionFen)}} · {{incomeLabel(detail.commission.status)}}</p><p v-if="detail.commission.reason">{{detail.commission.reason}}</p><RouterLink v-if="account.permissionCodes.includes('order.read')" :to="`/orders/${detail.id}`"><el-button>进入统一订单履约详情</el-button></RouterLink></template></section></el-dialog><AdminSelectedRowsDialog v-model="comparison" title="联盟订单对比" :rows="comparisonRows" :columns="[{key:'orderNo',label:'订单'},{key:'restaurant',label:'餐饮店'},{key:'table',label:'桌号'},{key:'status',label:'状态'},{key:'paid',label:'实付'},{key:'commission',label:'佣金'}]"/><OrderActionDialog :account="account" :order-id="operationId" :action="operation" @close="operation=null" @updated="operationUpdated" @notice="operationNotice=$event"/></section></template>
